-- ----------------------------
-- Table structure for event_outbox
-- ----------------------------
DROP TABLE IF EXISTS `event_outbox`;
CREATE TABLE `event_outbox`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `topic` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '目标 Kafka topic',
  `event_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '分区 key（如 userId/groupId）',
  `event_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务事件幂等 ID（同一 topic 内唯一）',
  `payload` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事件 JSON 体（控制事件，非媒体）',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING/PROCESSING/SENT/DEAD',
  `retry_count` int NOT NULL DEFAULT 0,
  `next_attempt_at` datetime NOT NULL COMMENT '下次投递时间（失败指数退避）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `sent_at` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_outbox_topic_event`(`topic` ASC, `event_id` ASC) USING BTREE,
  INDEX `idx_outbox_claim`(`status` ASC, `next_attempt_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 41 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Kafka transactional outbox' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of event_outbox
-- ----------------------------

