-- Table structure for kafka_event_ledger
-- ----------------------------
DROP TABLE IF EXISTS `kafka_event_ledger`;
CREATE TABLE `kafka_event_ledger`  (
  `topic` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `event_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `processed_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`topic`, `event_id`) USING BTREE,
  INDEX `idx_ledger_processed_at`(`processed_at` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Kafka consumer idempotency ledger' ROW_FORMAT = Dynamic;

