-- ----------------------------
-- Table structure for rtc_call_device
-- ----------------------------
DROP TABLE IF EXISTS `rtc_call_device`;
CREATE TABLE `rtc_call_device`  (
  `id` bigint NOT NULL COMMENT '雪花ID',
  `call_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `user_id` bigint NOT NULL,
  `device_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '客户端持久化设备标识',
  `state` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'RINGING/ACCEPTED/REJECTED/CANCELLED/CONNECTED/LEFT',
  `accepted_at` datetime NULL DEFAULT NULL,
  `rejected_at` datetime NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_call_user_device`(`call_id` ASC, `user_id` ASC, `device_id` ASC) USING BTREE,
  INDEX `idx_call_device_state`(`call_id` ASC, `state` ASC) USING BTREE,
  INDEX `idx_user_device_state`(`user_id` ASC, `state` ASC, `update_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'RTC 通话设备级状态' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of rtc_call_device
-- ----------------------------

-- ----------------------------
-- Table structure for rtc_call_event
-- ----------------------------
DROP TABLE IF EXISTS `rtc_call_event`;
CREATE TABLE `rtc_call_event`  (
  `id` bigint NOT NULL COMMENT '雪花ID',
  `event_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '全局唯一事件ID(幂等)',
  `call_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '通话ID',
  `participant_id` bigint NOT NULL DEFAULT 0 COMMENT '触发参与者用户ID, 0=系统事件',
  `kind` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'call.request/call.accept/call.reject/call.cancel/call.join/call.leave/call.hangup/call.state/call.connected/call.ended/call.expired/call.failed',
  `seq` bigint NOT NULL COMMENT '同一(call_id,participant_id)单调递增序号',
  `event_version` bigint NOT NULL DEFAULT 0,
  `occurred_at` datetime NOT NULL COMMENT '事件发生时间',
  `payload` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '事件负载 JSON',
  `trace_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '链路追踪ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_event_id`(`event_id` ASC) USING BTREE,
  INDEX `idx_call_participant_seq`(`call_id` ASC, `participant_id` ASC, `seq` ASC) USING BTREE,
  INDEX `idx_call_time`(`call_id` ASC, `occurred_at` ASC) USING BTREE,
  INDEX `idx_call_event_version`(`call_id` ASC, `event_version` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'RTC 通话事件账本' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of rtc_call_event
-- ----------------------------

-- ----------------------------
-- Table structure for rtc_call_participant
-- ----------------------------
DROP TABLE IF EXISTS `rtc_call_participant`;
CREATE TABLE `rtc_call_participant`  (
  `id` bigint NOT NULL COMMENT '雪花ID',
  `call_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '通话ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `role` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'member' COMMENT 'initiator|member',
  `state` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'INVITED/RINGING/JOINING/CONNECTED/RECONNECTING/LEFT/REJECTED/CANCELLED/FAILED',
  `joined_at` datetime NULL DEFAULT NULL COMMENT '加入时间',
  `left_at` datetime NULL DEFAULT NULL COMMENT '离开时间',
  `reason` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '离开/失败原因',
  `profile_snapshot` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '历史展示快照,不作为权限来源',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_call_user`(`call_id` ASC, `user_id` ASC) USING BTREE,
  INDEX `idx_call`(`call_id` ASC) USING BTREE,
  INDEX `idx_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_participant_user_state_call`(`user_id` ASC, `state` ASC, `call_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'RTC 通话参与者表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of rtc_call_participant
-- ----------------------------

-- ----------------------------
-- Table structure for rtc_call_session
-- ----------------------------
DROP TABLE IF EXISTS `rtc_call_session`;
CREATE TABLE `rtc_call_session`  (
  `id` bigint NOT NULL COMMENT '雪花ID',
  `call_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '全局不可变通话ID',
  `room_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'provider room ID (livekit/p2p-fallback)',
  `scope` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'direct|group|live-interactive',
  `mode` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'audio|video',
  `initiator_id` bigint NOT NULL COMMENT '发起者用户ID',
  `provider` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'livekit' COMMENT 'livekit|p2p-fallback|legacy',
  `state` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'CREATED/RINGING/ACCEPTED/NEGOTIATING/CONNECTED/ENDING/REJECTED/CANCELLED/EXPIRED/FAILED/ENDED',
  `state_version` bigint NOT NULL DEFAULT 0,
  `client_request_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '发起幂等键(唯一)',
  `ring_at` datetime NULL DEFAULT NULL,
  `expires_at` datetime NULL DEFAULT NULL COMMENT 'ringing/negotiating TTL 过期时间',
  `connected_at` datetime NULL DEFAULT NULL COMMENT '首次进入 CONNECTED 时间',
  `ended_at` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `end_reason` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'hangup/rejected/expired/failed/permission/provider',
  `trace_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '链路追踪ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_call_id`(`call_id` ASC) USING BTREE,
  UNIQUE INDEX `uk_client_request_id`(`client_request_id` ASC) USING BTREE,
  INDEX `idx_state_expires`(`state` ASC, `expires_at` ASC) USING BTREE,
  INDEX `idx_call_initiator_created`(`initiator_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_call_state_version`(`call_id` ASC, `state_version` ASC) USING BTREE,
  INDEX `idx_call_state_updated`(`state` ASC, `update_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'RTC 通话会话表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of rtc_call_session
-- ----------------------------

-- ----------------------------
-- Table structure for rtc_webhook_ledger
-- ----------------------------
DROP TABLE IF EXISTS `rtc_webhook_ledger`;
CREATE TABLE `rtc_webhook_ledger`  (
  `id` bigint NOT NULL COMMENT '雪花ID',
  `event_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'LiveKit webhook 事件ID(全局唯一,幂等)',
  `call_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '解析出的通话ID,未知时为空',
  `event_type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'room_started/room_finished/participant_joined/participant_left/track_*/...',
  `payload` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '签名校验后的原始负载 JSON(审计)',
  `received_at` datetime NOT NULL COMMENT '接收时间',
  `processed` tinyint NOT NULL DEFAULT 1 COMMENT '1=已消费(去重后首次处理)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_event_id`(`event_id` ASC) USING BTREE,
  INDEX `idx_call`(`call_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'RTC provider webhook 账本' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of rtc_webhook_ledger
-- ----------------------------

-- ----------------------------
-- Table structure for t_active_session
-- ----------------------------
DROP TABLE IF EXISTS `t_active_session`;
CREATE TABLE `t_active_session`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `token_hash` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `device_fingerprint` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `device_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `ip` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `city` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `browser_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `browser_version` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `device_os` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `os_version` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `screen_width` int NULL DEFAULT NULL,
  `screen_height` int NULL DEFAULT NULL,
  `cpu_cores` int NULL DEFAULT NULL,
  `device_memory_gb` int NULL DEFAULT NULL,
  `gpu_renderer` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
