-- ----------------------------
-- Table structure for t_live_room
-- ----------------------------
DROP TABLE IF EXISTS `t_live_room`;
CREATE TABLE `t_live_room`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '直播间ID',
  `host_user_id` bigint NOT NULL COMMENT '主播用户ID',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '直播标题',
  `cover_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '封面图URL',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'PREVIEW' COMMENT '状态: PREVIEW=预览(未开播), LIVE=直播中, ENDED=已结束',
  `viewer_count` int NULL DEFAULT 0 COMMENT '当前观看人数',
  `total_viewers` int NULL DEFAULT 0 COMMENT '累计观看人数',
  `like_count` int NULL DEFAULT 0 COMMENT '点赞数',
  `stream_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '推流地址(预留)',
  `play_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '播放地址(预留)',
  `srt_stream_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT 'SRT流ID',
  `rtmp_stream_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT 'RTMP推流密钥',
  `target_bitrate` int NULL DEFAULT 4000000 COMMENT '目标码率(bps)',
  `max_bitrate` int NULL DEFAULT 8000000 COMMENT '最大码率(bps)',
  `min_bitrate` int NULL DEFAULT 500000 COMMENT '最小码率(bps)',
  `encoder_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'nvenc' COMMENT '编码器类型: nvenc/x264/x265',
  `codec` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'av1' COMMENT '编码格式: av1/h265/h264',
  `enable_beauty` tinyint NULL DEFAULT 1 COMMENT '是否启用美颜',
  `enable_hdr` tinyint NULL DEFAULT 0 COMMENT '是否启用HDR',
  `capture_fps` double NULL DEFAULT 0 COMMENT '采集帧率',
  `encode_fps` double NULL DEFAULT 0 COMMENT '编码帧率',
  `gpu_usage` int NULL DEFAULT 0 COMMENT 'GPU使用率(%)',
  `cpu_usage` int NULL DEFAULT 0 COMMENT 'CPU使用率(%)',
  `is_delete` tinyint NULL DEFAULT 0 COMMENT '软删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_host_user`(`host_user_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_srt_stream`(`srt_stream_id` ASC) USING BTREE,
  INDEX `idx_codec`(`codec` ASC) USING BTREE,
  INDEX `idx_encoder`(`encoder_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '直播间表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_live_room
-- ----------------------------

-- ----------------------------
-- Table structure for t_login_history
-- ----------------------------
DROP TABLE IF EXISTS `t_login_history`;
CREATE TABLE `t_login_history`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '登录邮箱',
  `login_method` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '登录方式: password/code',
  `login_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'success' COMMENT 'success/fail',
  `ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '登录IP',
  `country` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '国家',
  `region` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '省/州',
  `city` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '城市',
  `isp` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'ISP运营商',
  `device_fingerprint` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '综合设备指纹hash',
  `user_agent_raw` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '原始User-Agent',
  `device_os` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作系统',
  `os_version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '系统版本',
  `browser_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '浏览器名称',
  `browser_version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '浏览器版本',
  `browser_language` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '浏览器语言',
  `screen_width` int NULL DEFAULT NULL COMMENT '屏幕宽度',
  `screen_height` int NULL DEFAULT NULL COMMENT '屏幕高度',
  `color_depth` int NULL DEFAULT NULL COMMENT '色深',
  `pixel_ratio` decimal(4, 2) NULL DEFAULT NULL COMMENT '设备像素比',
  `cpu_cores` int NULL DEFAULT NULL COMMENT 'CPU核心数',
  `device_memory_gb` int NULL DEFAULT NULL COMMENT '设备内存(GB)',
  `gpu_renderer` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'GPU渲染器信息',
  `connection_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '网络类型: 4g/wifi/ethernet',
  `platform_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '平台: Win32/MacIntel',
  `touch_support` tinyint NULL DEFAULT 0 COMMENT '是否触屏',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_user_time`(`user_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_ip`(`ip` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 135 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '登录历史/设备记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_login_history
-- ----------------------------

-- ----------------------------
-- Table structure for t_message
-- ----------------------------
DROP TABLE IF EXISTS `t_message`;
CREATE TABLE `t_message`  (
  `id` bigint NOT NULL COMMENT '消息ID',
  `from_user_id` bigint NOT NULL COMMENT '发送者ID',
  `to_user_id` bigint NOT NULL COMMENT '接收者ID',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '消息内容',
  `msg_type` tinyint NULL DEFAULT 1 COMMENT '消息类型: 1文本 2图片 3语音 4视频 5红包',
  `extra` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '附加数据(图片/语音url等)',
  `is_read` tinyint NULL DEFAULT 0 COMMENT '是否已读',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发送时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_from_to`(`from_user_id` ASC, `to_user_id` ASC) USING BTREE,
  INDEX `idx_conversation`(`from_user_id` ASC, `to_user_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_receiver_read`(`to_user_id` ASC, `is_read` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '私聊消息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_message
-- ----------------------------

-- ----------------------------
-- Table structure for t_music
-- ----------------------------
DROP TABLE IF EXISTS `t_music`;
CREATE TABLE `t_music`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '歌曲名',
  `artist` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '歌手',
  `album` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '专辑',
  `cover_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '封面图',
  `duration` int NULL DEFAULT 0 COMMENT '时长(秒)',
  `source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'netease' COMMENT '来源: netease/local',
  `source_id` bigint NULL DEFAULT NULL COMMENT '来源ID(如网易云歌曲ID)',
  `play_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '播放地址',
  `lyric` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '歌词',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'APPROVED' COMMENT 'Review status: PENDING/APPROVED/REJECTED',
  `review_comment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT 'Review comment / reject reason',
  `reviewed_by` bigint NULL DEFAULT 0 COMMENT 'Reviewer ID',
  `review_time` datetime NULL DEFAULT NULL COMMENT 'Review time',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_music_source`(`source` ASC, `source_id` ASC) USING BTREE,
  INDEX `idx_music_name`(`name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '音乐曲库' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_music
-- ----------------------------

-- ----------------------------
-- Table structure for t_notification
-- ----------------------------
DROP TABLE IF EXISTS `t_notification`;
CREATE TABLE `t_notification`  (
  `id` bigint NOT NULL COMMENT '通知ID',
  `user_id` bigint NOT NULL COMMENT '通知接收者ID',
  `from_user_id` bigint NULL DEFAULT 0 COMMENT '触发者ID',
  `type` tinyint NOT NULL COMMENT '通知类型: 1关注 2点赞 3评论 4收藏 5@提及',
  `video_id` bigint NULL DEFAULT 0 COMMENT '关联视频ID',
  `comment_id` bigint NULL DEFAULT 0 COMMENT '关联评论ID',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '通知摘要',
  `is_read` tinyint NULL DEFAULT 0 COMMENT '是否已读',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '通知时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_read`(`user_id` ASC, `is_read` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_user_type`(`user_id` ASC, `type` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '互动通知表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_notification
-- ----------------------------

-- ----------------------------
-- Table structure for t_order
-- ----------------------------
DROP TABLE IF EXISTS `t_order`;
CREATE TABLE `t_order`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '买家ID',
  `seller_id` bigint NOT NULL COMMENT '卖家ID',
  `goods_id` bigint NOT NULL COMMENT '商品ID',
  `goods_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '商品名称快照',
  `goods_cover` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '商品封面快照',
  `price` decimal(10, 2) NULL DEFAULT NULL COMMENT '成交单价',
  `quantity` int NULL DEFAULT 1 COMMENT '数量',
  `total_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '总金额',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'PENDING' COMMENT 'PENDING/PAID/SHIPPED/RECEIVED/CANCELLED',
  `receiver_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '收货人',
  `receiver_phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '收货电话',
  `receiver_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '收货地址',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '买家备注',
  `is_delete` tinyint NULL DEFAULT 0,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `payment_method` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'wallet' COMMENT 'wallet/wechat/alipay/bank',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_goods_id`(`goods_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_order
-- ----------------------------

-- ----------------------------
-- Table structure for t_payment_audit
-- ----------------------------
DROP TABLE IF EXISTS `t_payment_audit`;
CREATE TABLE `t_payment_audit`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `order_id` bigint NULL DEFAULT NULL COMMENT '关联订单ID',
  `action` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'PAY/RECHARGE/REFUND/CANCEL',
  `request_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '请求金额',
  `order_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '订单金额',
  `balance_before` decimal(10, 2) NULL DEFAULT NULL COMMENT '交易前余额',
  `balance_after` decimal(10, 2) NULL DEFAULT NULL COMMENT '交易后余额',
  `payment_method` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '支付方式',
  `result` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'PASS/FAIL',
  `fail_reason` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '失败原因',
  `ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '请求IP',
  `user_agent` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'UA',
  `risk_level` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'LOW' COMMENT 'LOW/MEDIUM/HIGH',
  `risk_detail` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '风险详情',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_order_id`(`order_id` ASC) USING BTREE,
  INDEX `idx_result`(`result` ASC) USING BTREE,
  INDEX `idx_risk`(`risk_level` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '支付安全审计日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_payment_audit
-- ----------------------------

-- ----------------------------
-- Table structure for t_search_alias
-- ----------------------------
DROP TABLE IF EXISTS `t_search_alias`;
CREATE TABLE `t_search_alias`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `alias` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '用户输入的搜索词',
  `target_category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '映射到的目标分类',
  `target_keyword` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '映射到的目标关键词',
  `weight` double NULL DEFAULT 0.8 COMMENT '权重 0-1',
  `source` tinyint NULL DEFAULT 0 COMMENT '0=运营配置 1=自动挖掘',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_alias`(`alias` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 160 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '搜索别名映射' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_search_alias
-- ----------------------------

-- ----------------------------
-- Table structure for t_search_history
-- ----------------------------
DROP TABLE IF EXISTS `t_search_history`;
CREATE TABLE `t_search_history`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `keyword` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '搜索关键词',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '搜索时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_time`(`user_id` ASC, `create_time` DESC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 171 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '搜索历史表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_search_history
-- ----------------------------

-- ----------------------------
-- Table structure for t_shop_message
-- ----------------------------
DROP TABLE IF EXISTS `t_shop_message`;
CREATE TABLE `t_shop_message`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '接收用户ID',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '消息标题',
  `content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '消息内容',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'cart/order/service',
  `related_id` bigint NULL DEFAULT NULL COMMENT '关联ID (商品ID/订单ID)',
  `is_read` tinyint NULL DEFAULT 0 COMMENT '0=未读 1=已读',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_user_read`(`user_id` ASC, `is_read` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '商城消息通知' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_shop_message
-- ----------------------------

-- ----------------------------
-- Table structure for t_system_notice
-- ----------------------------
DROP TABLE IF EXISTS `t_system_notice`;
CREATE TABLE `t_system_notice`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '接收通知的用户ID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '通知标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '通知详细内容',
  `type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'system' COMMENT '类型: friend_accepted/login/publish_video/publish_image/publish_text/system',
  `is_read` tinyint NULL DEFAULT 0 COMMENT '0未读 1已读',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_user_read`(`user_id` ASC, `is_read` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 233 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '系统通知表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_system_notice
-- ----------------------------

-- ----------------------------
-- Table structure for t_user
-- ----------------------------
DROP TABLE IF EXISTS `t_user`;
CREATE TABLE `t_user`  (
  `uid` bigint NOT NULL COMMENT '用户ID',
  `unique_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '抖音号',
  `nickname` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '抖音用户' COMMENT '昵称',
  `signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '个性签名',
  `gender` tinyint NULL DEFAULT 0 COMMENT '性别: 0未知 1男 2女',
  `birthday` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '生日',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '省份',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '城市',
  `avatar_168_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '头像小图',
  `avatar_300_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '头像大图',
  `cover_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '个人主页背景',
  `follower_count` bigint NULL DEFAULT 0 COMMENT '粉丝数',
  `following_count` bigint NULL DEFAULT 0 COMMENT '关注数',
  `total_favorited` bigint NULL DEFAULT 0 COMMENT '获赞总数',
  `video_count` int NULL DEFAULT 0 COMMENT '作品数',
  `phone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '手机号',
  `email` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '邮箱',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '密码(bcrypt)',
  `is_delete` tinyint NULL DEFAULT 0 COMMENT '逻辑删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `visitor_display` tinyint NULL DEFAULT 0 COMMENT '主页访客展示开关: 0关闭 1开启',
  `role` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'user' COMMENT '角色: user=普通用户, merchant=SeekFlow商家',
  `balance` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '账户余额',
  `pay_salt` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '支付签名盐值',
  PRIMARY KEY (`uid`) USING BTREE,
  INDEX `idx_unique_id`(`unique_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_user
-- ----------------------------

-- ----------------------------
-- Table structure for t_user_behavior_log
-- ----------------------------
DROP TABLE IF EXISTS `t_user_behavior_log`;
CREATE TABLE `t_user_behavior_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `video_id` bigint NULL DEFAULT NULL,
  `author_id` bigint NULL DEFAULT NULL,
  `target_user_id` bigint NULL DEFAULT NULL COMMENT '社交行为目标用户',
  `action_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'VIEW/LIKE/COLLECT/SHARE/COMMENT/FOLLOW/UNFOLLOW/PROFILE_VIEW/SEARCH/COMMENT_LIKE/COMMENT_DISLIKE/SCROLL_SKIP',
  `traffic_source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '流量来源',
  `value_double_1` double NULL DEFAULT NULL COMMENT '通用数值字段1 (如观看时长)',
  `value_double_2` double NULL DEFAULT NULL COMMENT '通用数值字段2 (如完播率)',
  `value_int_1` int NULL DEFAULT NULL COMMENT '通用整数字段1 (如重复次数)',
  `value_str_1` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用字符串字段1 (如搜索词)',
  `session_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `device_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_behavior_user_time`(`user_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_behavior_user_action`(`user_id` ASC, `action_type` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_behavior_session`(`session_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_behavior_video`(`video_id` ASC, `action_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '统一用户行为日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_user_behavior_log
-- ----------------------------

-- ----------------------------
-- Table structure for t_user_content_profile
-- ----------------------------
DROP TABLE IF EXISTS `t_user_content_profile`;
CREATE TABLE `t_user_content_profile`  (
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `category_weights` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '内容分类偏好权重',
  `preferred_duration_min` double NULL DEFAULT NULL COMMENT '偏好最小时长(秒)',
  `preferred_duration_max` double NULL DEFAULT NULL COMMENT '偏好最大时长(秒)',
  `avg_completion_rate` double NULL DEFAULT 0 COMMENT '平均完播率',
  `preferred_bpm_min` double NULL DEFAULT NULL COMMENT '偏好BPM下限',
  `preferred_bpm_max` double NULL DEFAULT NULL COMMENT '偏好BPM上限',
  `preferred_energy` double NULL DEFAULT NULL COMMENT '偏好能量均值 0-1',
  `user_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '用户类型: silent/social/collector/explorer/follower',
  `total_watch_count` int NULL DEFAULT 0 COMMENT '总观看数',
  `total_interact_count` int NULL DEFAULT 0 COMMENT '总互动数',
  `content_vector` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '用户内容偏好向量(JSON float array, 512维)',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `short_term_vector` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '24h EMA 兴趣向量 JSON',
  `long_term_vector` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '30d EMA 兴趣向量 JSON',
  `creator_affinity` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '创作者亲和力 JSON {authorId: score}',
  `avg_watch_duration` double NULL DEFAULT 0 COMMENT '平均观看时长(秒)',
  `bounce_rate` double NULL DEFAULT 0 COMMENT '快速划走率 (<3秒)',
  `like_rate` double NULL DEFAULT 0 COMMENT '点赞率 (like/view)',
  `collect_rate` double NULL DEFAULT 0 COMMENT '收藏率',
  `share_rate` double NULL DEFAULT 0 COMMENT '分享率',
  `comment_rate` double NULL DEFAULT 0 COMMENT '评论率',
  `repeat_view_rate` double NULL DEFAULT 0 COMMENT '重复观看率',
  `social_engagement_rate` double NULL DEFAULT 0 COMMENT '对关注作者的互动占比',
  `profile_visit_count` int NULL DEFAULT 0 COMMENT '浏览他人主页次数',
  `search_frequency` double NULL DEFAULT 0 COMMENT '搜索频率(次/会话)',
  `recent_search_queries` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '近期搜索词 JSON',
  `traffic_sources` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '流量来源分布 JSON {source: ratio}',
  `active_hours` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '活跃时段分布 JSON [0-23]',
  `avg_session_duration` double NULL DEFAULT 0 COMMENT '平均会话时长(秒)',
  `active_days_last_week` int NULL DEFAULT 0 COMMENT '近7天活跃天数',
  `user_segment` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'new_user' COMMENT '用户分层: new_user/light/medium/heavy',
  `total_view_count` int NULL DEFAULT 0 COMMENT '总观看视频数',
  `total_like_count` int NULL DEFAULT 0 COMMENT '总点赞数',
  `total_collect_count` int NULL DEFAULT 0 COMMENT '总收藏数',
  `total_share_count` int NULL DEFAULT 0 COMMENT '总分享数',
  `total_comment_count` int NULL DEFAULT 0 COMMENT '总评论数',
  `total_search_count` int NULL DEFAULT 0 COMMENT '总搜索次数',
  `total_watch_time_sec` bigint NULL DEFAULT 0 COMMENT '总观看时长(秒)',
  PRIMARY KEY (`user_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户内容偏好画像表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_user_content_profile
-- ----------------------------

-- ----------------------------
-- Table structure for t_video
-- ----------------------------
DROP TABLE IF EXISTS `t_video`;
CREATE TABLE `t_video`  (
  `id` bigint NOT NULL COMMENT '视频ID',
  `video_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '视频地址',
  `cover_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '封面地址',
  `desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '标题描述',
  `duration` double NULL DEFAULT 0 COMMENT '视频时长(秒)',
  `width` int NULL DEFAULT 0 COMMENT '宽度',
  `height` int NULL DEFAULT 0 COMMENT '高度',
  `author_user_id` bigint NULL DEFAULT 0 COMMENT '作者ID',
  `music_id` bigint NULL DEFAULT 0 COMMENT '音乐ID',
  `music_title` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '音乐标题',
  `type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'recommend-video' COMMENT '视频类型',
  `like_count` bigint NULL DEFAULT 0 COMMENT '点赞数',
  `comment_count` bigint NULL DEFAULT 0 COMMENT '评论数',
  `share_count` bigint NULL DEFAULT 0 COMMENT '分享数',
  `collect_count` bigint NULL DEFAULT 0 COMMENT '收藏数',
  `play_count` bigint NULL DEFAULT 0 COMMENT '播放数',
  `is_delete` tinyint NULL DEFAULT 0 COMMENT '逻辑删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `bgm_start_offset` double NULL DEFAULT 0 COMMENT 'BGM起始偏移(秒)',
  `bgm_volume` double NULL DEFAULT 0.7 COMMENT 'BGM音量(0-1), 0.7=70%',
  `image_urls` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '多图URL列表(JSON数组), 用于图文轮播帖子',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'APPROVED' COMMENT '审核状态: PENDING/APPROVED/REJECTED',
  `review_comment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '审核意见/驳回原因',
  `reviewed_by` bigint NULL DEFAULT 0 COMMENT '审核人ID',
  `review_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_author`(`author_user_id` ASC) USING BTREE,
  INDEX `idx_type`(`type` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '视频表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_video
-- ----------------------------

-- ----------------------------
-- Table structure for t_video_collect
-- ----------------------------
DROP TABLE IF EXISTS `t_video_collect`;
CREATE TABLE `t_video_collect`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `video_id` bigint NOT NULL COMMENT '视频ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_collect`(`user_id` ASC, `video_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '收藏记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_video_collect
-- ----------------------------

-- ----------------------------
-- Table structure for t_video_content
-- ----------------------------
DROP TABLE IF EXISTS `t_video_content`;
CREATE TABLE `t_video_content`  (
  `video_id` bigint NOT NULL COMMENT '视频ID',
  `visual_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'Qwen2.5-VL 对画面的自然语言描述',
  `scene_tags` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '场景标签(JSON): [\"厨房\",\"室内\",\"暖色调\"]',
  `object_tags` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '物体标签(JSON): [\"美食\",\"人物\",\"铁锅\"]',
  `visual_embedding` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '视觉向量(JSON float array, 1024维)',
  `categories` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '多标签分类JSON: [{\"label\":\"美食\",\"confidence\":0.85}, ...]',
  `mood` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '情绪/氛围: 欢乐/治愈/紧张/...',
  `style` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '视频风格: Vlog/教程/混剪/...',
  `quality_label` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '画质标签: 精良专业/清晰良好/一般/模糊',
  `music_genre` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '音乐流派: 流行/电子/古风/纯音乐/...',
  `content_attributes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '内容属性JSON: [\"有人脸\",\"有字幕\",\"室外拍摄\",...]',
  `transcript` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'Whisper 语音转录全文',
  `asr_keywords` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'ASR关键词JSON array',
  `has_speech` tinyint(1) NULL DEFAULT NULL COMMENT '是否有语音内容',
  `face_count` double NULL DEFAULT NULL COMMENT '平均每帧人脸数',
  `face_ratio` double NULL DEFAULT NULL COMMENT '人脸占画面比例 0-1',
  `is_closeup` tinyint(1) NULL DEFAULT NULL COMMENT '是否为特写镜头',
  `is_single_person` tinyint(1) NULL DEFAULT NULL COMMENT '是否为单人出镜',
  `is_multi_person` tinyint(1) NULL DEFAULT NULL COMMENT '是否为多人场景',
  `music_bpm` double NULL DEFAULT NULL COMMENT 'BPM',
  `music_key` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '调性: C / Am / ...',
  `music_energy` double NULL DEFAULT NULL COMMENT '能量 0-1',
  `music_valence` double NULL DEFAULT NULL COMMENT '情绪效价 0-1 (欢快-悲伤)',
  `music_spectral` double NULL DEFAULT NULL COMMENT '频谱质心 (明亮-暗淡)',
  `music_rolloff` double NULL DEFAULT NULL COMMENT '频谱滚降 (明亮度)',
  `music_bandwidth` double NULL DEFAULT NULL COMMENT '频谱带宽',
  `music_zcr` double NULL DEFAULT NULL COMMENT '过零率 (语音/非语音指示)',
  `music_onset_rate` double NULL DEFAULT NULL COMMENT '节拍密度 (节奏复杂度)',
  `music_mfcc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'MFCC特征(JSON float array, 13维)',
  `audio_has_music` tinyint(1) NULL DEFAULT NULL COMMENT '是否包含音乐',
  `keywords` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '关键词(JSON): [\"美食\",\"红烧肉\",\"教程\"]',
  `text_category` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类: 美食/舞蹈/搞笑/知识/旅行/音乐/...',
  `text_embedding` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '文本语义向量(JSON float array, 1024维)',
  `content_vector` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '融合内容向量(JSON float array, 512维)',
  `quality_score` double NULL DEFAULT 0 COMMENT '预估内容质量分 0-1',
  `extract_status` tinyint NULL DEFAULT 0 COMMENT '提取状态: 0=待处理 1=完成 2=失败',
  `extract_time_ms` int NULL DEFAULT 0 COMMENT '特征提取耗时(毫秒)',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`video_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '视频内容特征表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_video_content
-- ----------------------------

-- ----------------------------
-- Table structure for t_video_exposure
-- ----------------------------
DROP TABLE IF EXISTS `t_video_exposure`;
CREATE TABLE `t_video_exposure`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `video_id` bigint NOT NULL COMMENT '视频ID',
  `exposure_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '曝光时间',
  `swipe_seconds` double NULL DEFAULT 0 COMMENT '停留秒数(<3=快速划过)',
  `clicked` tinyint NULL DEFAULT 0 COMMENT '是否点击互动(评论/点赞等)',
  `traffic_source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'HOME_RECOMMEND' COMMENT '流量来源: HOME_RECOMMEND/SEARCH/USER_PROFILE/FOLLOWING/HASHTAG/EXTERNAL/SHARE',
  `session_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '会话ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_video_day`(`user_id` ASC, `video_id` ASC, `exposure_time` ASC) USING BTREE,
  INDEX `idx_user_time`(`user_id` ASC, `exposure_time` ASC) USING BTREE,
  INDEX `idx_video`(`video_id` ASC) USING BTREE,
  INDEX `idx_exposure_source`(`user_id` ASC, `traffic_source` ASC, `exposure_time` ASC) USING BTREE,
  INDEX `idx_exposure_session`(`session_id` ASC, `exposure_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 485 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '视频曝光记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_video_exposure
-- ----------------------------

-- ----------------------------
-- Table structure for t_video_tag
-- ----------------------------
DROP TABLE IF EXISTS `t_video_tag`;
CREATE TABLE `t_video_tag`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `video_id` bigint NOT NULL,
  `tag` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `source` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'auto' COMMENT 'manual/auto',
  `weight` double NULL DEFAULT 1 COMMENT '标签权重',
  `confidence` double NULL DEFAULT 0.5 COMMENT '置信度 0-1',
  `signal_count` int NULL DEFAULT 0 COMMENT '贡献此标签的行为信号次数',
  `ai_base` double NULL DEFAULT 0 COMMENT 'AI 基础分 (动态标签=0)',
  `last_signal` datetime NULL DEFAULT NULL COMMENT '最后一次收到信号的时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_video_tag`(`video_id` ASC, `tag` ASC) USING BTREE,
  INDEX `idx_tag`(`tag` ASC) USING BTREE,
  INDEX `idx_video_weight`(`video_id` ASC, `weight` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 164 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '视频标签表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_video_tag
-- ----------------------------

-- ----------------------------
-- Table structure for t_visitor
-- ----------------------------
DROP TABLE IF EXISTS `t_visitor`;
CREATE TABLE `t_visitor`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '被访问者(主页主人)',
  `visitor_id` bigint NOT NULL COMMENT '访问者',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '访问时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_visitor_id`(`visitor_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 61 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '访客记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_visitor
-- ----------------------------

-- ----------------------------
-- Table structure for t_wallet_transaction
-- ----------------------------
DROP TABLE IF EXISTS `t_wallet_transaction`;
CREATE TABLE `t_wallet_transaction`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'RECHARGE/PAY/REFUND',
  `amount` decimal(10, 2) NOT NULL COMMENT '金额',
  `balance_after` decimal(10, 2) NOT NULL COMMENT '交易后余额',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '钱包交易流水' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_wallet_transaction
-- ----------------------------

-- ----------------------------
-- Table structure for t_watch_history
-- ----------------------------
DROP TABLE IF EXISTS `t_watch_history`;
CREATE TABLE `t_watch_history`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '观看用户ID',
  `video_id` bigint NOT NULL COMMENT '视频ID',
  `author_user_id` bigint NOT NULL COMMENT '视频作者ID',
  `watch_duration` double NULL DEFAULT 0 COMMENT '已观看时长(秒)',
  `video_duration` double NULL DEFAULT 0 COMMENT '视频总时长(秒)',
  `finished` tinyint NULL DEFAULT 0 COMMENT '是否看完 0未看完 1已看完',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '首次观看时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后观看时间',
  `repeat_count` int NULL DEFAULT 1 COMMENT '重复观看次数',
  `traffic_source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'HOME_RECOMMEND' COMMENT '流量来源: HOME_RECOMMEND/SEARCH/USER_PROFILE/FOLLOWING/HASHTAG/EXTERNAL/SHARE',
  `session_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '会话ID',
  `swipe_seconds` double NULL DEFAULT NULL COMMENT '本次观看划走耗时(秒)',
  `last_position` double NULL DEFAULT NULL COMMENT '上次播放位置(秒), 用于断点续播',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_video`(`user_id` ASC, `video_id` ASC) USING BTREE,
  INDEX `idx_watch_source`(`user_id` ASC, `traffic_source` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_watch_session`(`session_id` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 135 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '视频观看记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_watch_history
-- ----------------------------

